'use strict';
const V7={tab:'accept',source:'all',category:'全部',location:'',uid:stored('sy-v7-uid'),filter:'all'};
if(typeof V7.uid!=='string'){V7.uid=vId();save('sy-v7-uid',V7.uid)}
const v7Nav=V2NAV.find(x=>x[0]==='community');if(v7Nav)v7Nav[1]='互助与任务';
const V7TYPES=['现场拍照与信息核实','物资运送','代取物品','出行陪伴','设备协助','其他'];
const v7Rows=()=>stored('sy-v7-tasks');
const v7Reviews=()=>stored('sy-v7-reviews');
const v7Owner=t=>t.owner===V7.uid;
const v7Worker=t=>t.worker===V7.uid;
let v7Mine=t=>v7Owner(t)||v7Worker(t);
const v7WeatherBase=vWeather;
vWeather=function(){return v7WeatherBase().replace(/\slist="[^"]*"/g,'').replace(/<datalist\b[\s\S]*?<\/datalist>/g,'').replace('placeholder="站点或纬度,经度"','placeholder="输入天气地点或纬度,经度"')};
function v7Distance(t){const a=vResolve(V7.location),b=vResolve(t.coordinates||t.place);if(!a||!b)return '距离未知';const rad=x=>x*Math.PI/180,dlat=rad(b.lat-a.lat),dlon=rad(b.lon-a.lon),h=Math.sin(dlat/2)**2+Math.cos(rad(a.lat))*Math.cos(rad(b.lat))*Math.sin(dlon/2)**2;return (6371*2*Math.asin(Math.sqrt(h))).toFixed(1)+' km（直线）'}
function v7Reputation(id){const rows=v7Reviews().filter(r=>r.to===id);return {count:rows.length,average:rows.length?(rows.reduce((s,r)=>s+r.rating,0)/rows.length).toFixed(1):null,rows}}
function v7Progress(t){const steps=['审核中','待接单','已接单','待确认完成','已完成'],i=steps.indexOf(t.status);return `<div class="v7progress">${steps.map((s,n)=>`<span class="${i>=n?'done':''}">${n+1}. ${s}</span>`).join('')}</div>${t.status==='已取消'||t.status==='审核未通过'?`<span class="tag orange">${t.status}</span>`:''}`}
function v7TaskCard(t){const own=v7Owner(t),worker=v7Worker(t),rep=v7Reputation(t.owner);return `<article class="v7task"><div class="row"><span class="tag ${t.source==='official'?'':'gray'}">${t.source==='official'?'官方任务':'私人任务'}${t.demo?' · 演示':''}</span><span class="tag orange">${esc(t.status)}</span></div><h3 data-original>${esc(t.title)}</h3><p>${esc(t.detail)}</p><div class="v7taskfacts"><span>分类<b>${esc(t.category)}</b></span><span>预计持续<b>${t.duration}分钟</b></span><span>难度（发布者自评）<b>${esc(t.difficulty)}</b></span><span>拟定奖励<b>${esc(t.rewardType)} ${t.reward}</b></span><span>地点<b>${esc(t.place)}</b></span><span>距我的位置<b>${v7Distance(t)}</b></span></div><div class="v7publisher"><button data-v7="profile" data-value="${t.owner}">${esc(t.ownerName)} · 查看主页</button><small>${rep.average?rep.average+'/5 · '+rep.count+'条本地评价':'暂无评价'}${t.demo?' · 虚构演示身份':''}</small></div><small>创建 ${esc(dateText(t.created))}${t.deadline?' · 截止 '+esc(dateText(t.deadline)):''}<br>接单情况：${t.worker?'已有人接单 · '+esc(t.workerName):'尚未接单'}；奖励未支付、未发放。</small>${v7Progress(t)}<div class="chips">${t.status==='待接单'&&!own?`<button class="primary" data-v7="accept" data-value="${t.id}">接受任务${t.demo?'（演示）':''}</button>`:''}${own&&t.status==='待接单'?'<span class="muted">你发布的任务，等待他人接单</span>':''}${worker&&t.status==='已接单'?`<button data-v7="complete" data-value="${t.id}">提交完成说明</button>`:''}${own&&t.status==='待确认完成'?`<button data-v7="confirm" data-value="${t.id}">确认完成</button>`:''}${worker&&t.demo&&t.status==='待确认完成'?`<button data-v7="demo-confirm" data-value="${t.id}">模拟发布者确认</button>`:''}${t.status==='已完成'&&v7Mine(t)?`<button data-v7="review" data-value="${t.id}">评价对方</button>`:''}${own&&['审核中','待接单'].includes(t.status)?`<button data-v7="cancel" data-value="${t.id}">取消任务</button>`:''}</div>${t.completion?`<div class="handlingnote">完成说明：${esc(t.completion)}</div>`:''}${t.auditNote?`<small>审核说明：${esc(t.auditNote)}</small>`:''}<details><summary>任务流转记录 · ${(t.history||[]).length}条</summary>${(t.history||[]).map(h=>`<p>${esc(dateText(h.time))} · ${esc(h.status)}${h.note?' · '+esc(h.note):''}</p>`).join('')||'<p>演示任务初始状态，无真实审核记录。</p>'}</details></article>`}
function v7TaskForm(){return `<form id="v7-task-form" class="feedbackform"><div class="field full"><label>任务标题</label><input name="title" required maxlength="100" placeholder="例如：拍摄某入口的当前现场情况"></div><div class="field"><label>任务分类</label><select name="category">${V7TYPES.map(t=>`<option>${t}</option>`).join('')}</select></div><div class="field"><label>预计持续时长（分钟）</label><input name="duration" type="number" min="1" max="1440" value="30" required></div><div class="field"><label>难度（自评）</label><select name="difficulty"><option>简单</option><option>一般</option><option>较复杂</option></select></div><div class="field"><label>拟定奖励类型</label><select name="rewardType"><option>无偿互助</option><option>积分</option><option>金额（元）</option></select></div><div class="field"><label>拟定奖励数量</label><input name="reward" type="number" min="0" max="100000" value="0" required></div><div class="field"><label>接单截止时间（可选）</label><input name="deadline" type="datetime-local"></div><div class="field full"><label>任务地点</label><input name="place" required maxlength="200" placeholder="小区、道路或具体入口"></div><div class="field full"><label>任务地点坐标（可选）</label><input name="coordinates" placeholder="纬度,经度；用于距离计算"></div><div class="field full"><label>我的位置（仅用于计算距离）</label><input name="myLocation" value="${esc(V7.location)}" placeholder="站点或纬度,经度"><button type="button" data-v7="preview-distance">计算任务地点距离</button><small id="v7-distance-preview">坐标未知时不估算距离；结果为直线距离。</small></div><div class="field full"><label>具体内容与完成标准</label><textarea name="detail" required maxlength="2000" placeholder="写明拍摄对象、交付物、可行条件和完成标准"></textarea></div><div class="full notice">只能发布私人任务；官方任务须由可核验机构接入。不要发布涉水、进入封闭区域等危险任务。审核与奖励目前仅为本地体验。</div><div class="full"><button class="primary">提交本地审核</button></div></form>`}
v5Community=function(){const tasks=v7Rows(),visible=tasks.filter(t=>['待接单','已接单'].includes(t.status)&&(V7.source==='all'||t.source===V7.source)&&(V7.category==='全部'||t.category===V7.category));return vHead('LOCAL HELP · SHARED CARE','互助与任务','让任务内容、进度和双方评价更清楚。当前仍是本浏览器体验。')+`<section class="v7communityhero"><div><span class="eyebrow">01 · 互助区</span><h2>需要帮助，或愿意出一份力。</h2><p>查看任务要求与发布者记录，量力参与。</p></div><div class="v7herostat"><b>${tasks.filter(t=>t.status==='待接单').length}</b><span>本地待接单任务（含演示）</span></div></section><section class="card"><div class="seg"><button data-v7="tab" data-value="accept" class="${V7.tab==='accept'?'active':''}">接受任务</button><button data-v7="tab" data-value="publish" class="${V7.tab==='publish'?'active':''}">发布任务</button></div>${V7.tab==='publish'?v7TaskForm()+`<h3 style="margin-top:24px">我发布的任务 · 进度</h3>${tasks.filter(v7Owner).map(v7TaskCard).join('')||'<div class="empty">提交任务后显示审核、接单与完成进度。</div>'}`:`<div class="v7filters"><div class="chips">${[['all','全部任务'],['official','官方任务'],['private','私人任务']].map(([v,t])=>`<button data-v7="source" data-value="${v}" class="${V7.source===v?'active':''}">${t}</button>`).join('')}</div><label>任务类型<select id="v7-category">${['全部',...V7TYPES].map(t=>`<option ${V7.category===t?'selected':''}>${t}</option>`).join('')}</select></label><form id="v7-location-form" class="queryform"><input name="location" value="${esc(V7.location)}" placeholder="我的位置：站点或纬度,经度"><button>计算距离</button></form></div><div class="v7taskgrid">${visible.map(v7TaskCard).join('')||'<div class="empty">暂无匹配任务。没有接入实时官方任务和跨用户任务库。</div>'}</div><button data-v7="seed">载入两条演示任务（非真实委托）</button>`}${v5End('互助任务')}</section><section class="card" style="margin-top:20px"><span class="eyebrow">02 · 信誉与双方评价</span><div class="row"><h2>帮助有记录，评价有依据。</h2><button data-v7="profile" data-value="${V7.uid}">查看我的信誉主页</button></div><p>任务确认完成后，发布者与接单者各自评价一次。无评价时保持“暂无评价”，不预填信用分。</p><small>当前评价仅是本地记录；真实平台需要实名认证、申诉和防刷机制。演示评价有独立标记。</small></section><section class="card" style="margin-top:20px"><span class="eyebrow">03 · 我的任务记录</span><div class="seg"><button data-v7="record-filter" data-value="all">全部</button><button data-v7="record-filter" data-value="published">我发布的</button><button data-v7="record-filter" data-value="accepted">我接单的</button></div>${tasks.filter(t=>V7.filter==='published'?v7Owner(t):V7.filter==='accepted'?v7Worker(t):v7Mine(t)).slice().reverse().map(v7TaskCard).join('')||'<div class="empty">发布和接单后，记录会显示在这里。</div>'}${v5End('我的任务记录')}</section><details class="card" style="margin-top:20px"><summary>旧版互助草稿 · ${stored('sy-v5-help').length}条</summary>${stored('sy-v5-help').map(x=>`<div class="listitem"><b>${esc(x.title)}</b><p>${esc(x.detail)} · ${esc(x.place)}</p><small>原始草稿保留，未自动转为已审核任务。</small></div>`).join('')||'没有旧版草稿'}</details><details class="card" style="margin-top:20px"><summary>捐赠渠道与进度 · 待接入</summary><p>没有已核验募捐项目与到账回执，暂不收款。</p></details>`};
v5Personal=function(){const tasks=v7Rows(),rep=v7Reputation(V7.uid),fb=stored('sy-v2-feedback');return `<section class="v7profilehero"><div class="v7herohead"><div class="v7avatar">${esc(V5.profile.name.slice(0,1)||'访')}</div><div><div class="eyebrow">YOUR RAINWISE SPACE</div><h1>${esc(V5.profile.name)}</h1><p>用户 · 游客体验 <span>本地资料</span></p></div><button data-v7="profile" data-value="${V7.uid}">查看我的信誉 ↗</button></div><div class="v7profilemetrics"><div><b>${fb.length}</b><span>反馈记录</span></div><div><b>${tasks.filter(t=>v7Mine(t)&&t.status==='已完成').length}</b><span>完成任务（含演示）</span></div><div><b>${rep.average||'—'}</b><span>${rep.count}条本地评价</span></div><div><b>0</b><span>可兑换积分 · 未接入</span></div></div></section><section class="card v7account"><div class="row"><div><h2>个人中心与账号资料</h2><p class="muted">账号标识：${esc(V5.profile.account)} · 无需注册即可体验</p></div><span class="tag gray">账号认证未接入</span></div><details class="v7edit"><summary>编辑个人资料与语言偏好</summary><form id="v5-profile" class="feedbackform"><div class="field"><label>显示名称</label><input name="name" value="${esc(V5.profile.name)}" required maxlength="40"></div><div class="field"><label>自定义账号标识</label><input name="account" value="${esc(V5.profile.account)}" maxlength="80"></div><div class="field"><label>语言偏好</label><select name="language"><option>中文</option><option ${V5.profile.language==='English'?'selected':''}>English</option></select></div><div class="full"><button class="primary">保存资料</button><small>完整英文翻译尚未接入。</small></div></form></details><div class="v7accountlinks"><button data-v2="page" data-value="community">我的互助与任务 →</button><button data-v2="page" data-value="feedback">反馈记录与回复 →</button><button data-v7="profile" data-value="${V7.uid}">信誉与评价 →</button></div><h3>我的快捷地址</h3><div class="v7addressgrid">${V5.addresses.map((a,i)=>`<div><small>${esc(a.label)}</small><b>${esc(a.address)}</b><button class="linkbutton" data-v5="delete-address" data-value="${i}">删除</button></div>`).join('')}<button data-v5="add-address">＋ 添加家／公司／学校</button></div><details class="v7edit"><summary>积分奖励与帮助中心</summary><p>有效反馈奖励、积分发放与物资兑换尚未接通，不以维护核验自动产生积分。</p><button data-v2="page" data-value="feedback">帮助与软件反馈</button></details>${v5End('个人资料')}</section>`};
function v7Profile(id){const rep=v7Reputation(id),tasks=v7Rows(),task=tasks.find(t=>t.owner===id||t.worker===id),name=id===V7.uid?V5.profile.name:task?.owner===id?task.ownerName:task?.workerName||'本地参与者';vDialog(name+' · 信誉主页',`<div class="v7miniprofile"><div class="v7avatar">${esc(name.slice(0,1))}</div><h2>${esc(name)}</h2><span class="tag gray">${task?.demo?'演示身份 · 非真实用户':'本地体验身份 · 未实名认证'}</span></div><div class="v7profilemetrics"><div><b>${rep.average||'—'}</b><span>平均评分 /5</span></div><div><b>${rep.count}</b><span>评价数量</span></div><div><b>${tasks.filter(t=>(t.owner===id||t.worker===id)&&t.status==='已完成').length}</b><span>完成任务（含演示）</span></div></div>${rep.rows.map(r=>`<div class="listitem"><b>${r.rating}/5 ${r.demo?'· 演示评价':''}</b><p>${esc(r.text)}</p><small>${esc(dateText(r.time))} · ${r.role}</small></div>`).join('')||'<div class="empty">暂无评价，不代表已经获得信誉认证。</div>'}`)}
function v7SaveAction(id,action,note=''){const rows=v7Rows(),t=rows.find(x=>x.id===id);if(!t)return false;const now=businessNow().toISOString();if(action==='accept'){if(t.status!=='待接单'||v7Owner(t)||t.worker||(t.deadline&&new Date(t.deadline+':00+08:00')<businessNow()))return false;t.worker=V7.uid;t.workerName=V5.profile.name;t.status='已接单'}else if(action==='complete'){if(!v7Worker(t)||t.status!=='已接单'||!note.trim())return false;t.status='待确认完成';t.completion=note.trim()}else if(action==='confirm'){if(!v7Owner(t)||t.status!=='待确认完成')return false;t.status='已完成'}else if(action==='demo-confirm'){if(!t.demo||!v7Worker(t)||t.status!=='待确认完成')return false;t.status='已完成'}else if(action==='cancel'){if(!v7Owner(t)||!['审核中','待接单'].includes(t.status))return false;t.status='已取消'}else if(action==='approve'||action==='reject'){if(V3.role!=='maintainer'||t.status!=='审核中')return false;t.status=action==='approve'?'待接单':'审核未通过';t.auditNote=note||'维护游客本地审核';}else return false;t.updated=now;t.history=t.history||[];t.history.push({time:now,action,status:t.status,note});save('sy-v7-tasks',rows);return true}
function v7SaveReview(id,rating,text){const t=v7Rows().find(t=>t.id===id);if(!t||t.status!=='已完成'||!v7Mine(t)||!Number.isInteger(rating)||rating<1||rating>5||!text.trim())return false;const rows=v7Reviews();if(rows.some(r=>r.taskId===id&&r.from===V7.uid))return false;rows.push({taskId:id,from:V7.uid,to:v7Owner(t)?t.worker:t.owner,role:v7Owner(t)?'发布者评价接单者':'接单者评价发布者',rating,text:text.trim(),time:businessNow().toISOString(),demo:!!t.demo});save('sy-v7-reviews',rows);return true}
function v7Seed(){const rows=v7Rows();if(rows.some(t=>t.demo))return toast('演示任务已载入');const now=businessNow().toISOString();rows.push(...[{title:'拍摄公开步道入口状态',category:V7TYPES[0],place:'湖贝',source:'official',ownerName:'示例机构（非真实委托）',duration:15},{title:'协助代取雨具',category:V7TYPES[2],place:'罗湖',source:'private',ownerName:'示例居民（虚构）',duration:30}].map((x,i)=>({...x,id:vId(),owner:'demo-owner-'+i,detail:'仅在正常开放、无危险区域演示任务流程；不代表真实需求。',difficulty:'简单',rewardType:'演示积分',reward:10,created:now,updated:now,status:'待接单',demo:true,history:[]})));save('sy-v7-tasks',rows)}
const v7WorkspaceBase=v3Workspace;
v3Workspace=function(){const tasks=v7Rows().filter(t=>t.status==='审核中');return v7WorkspaceBase()+`<section class="card" style="margin-top:20px"><h2>私人任务本地审核 · ${tasks.length}条</h2>${tasks.map(t=>`<div class="listitem"><h3 data-original>${esc(t.title)}</h3><p>${esc(t.place)} · ${esc(t.category)} · ${t.duration}分钟 · ${esc(t.difficulty)} · 拟定奖励 ${esc(t.rewardType)} ${t.reward}</p><p>${esc(t.detail)}</p><button data-v7="approve" data-value="${t.id}">本地审核通过</button><button data-v7="reject" data-value="${t.id}">本地审核不通过</button></div>`).join('')||'<div class="empty">暂无待审核私人任务。</div>'}<small>维护游客标记不等于官方背书；无法核验任务条件时应保持待审核。</small></section>`};
document.addEventListener('click',e=>{const b=e.target.closest('[data-v7]');if(!b)return;const a=b.dataset.v7,v=b.dataset.value;vDraft();if(a==='preview-distance'){const f=Object.fromEntries(new FormData(b.closest('form')));V7.location=f.myLocation||'';const el=document.getElementById('v7-distance-preview');if(el)el.textContent=v7Distance({place:f.place,coordinates:f.coordinates});return}if(a==='tab')V7.tab=v;if(a==='source')V7.source=v;if(a==='record-filter')V7.filter=v;if(a==='profile')return v7Profile(v);if(a==='seed')v7Seed();if(a==='complete')return vDialog('提交完成说明',`<form id="v7-complete-form" class="feedbackform"><input name="id" type="hidden" value="${esc(v)}"><textarea name="note" required placeholder="说明完成了什么、交付内容是什么"></textarea><button class="primary">提交完成说明</button></form>`);if(a==='review')return vDialog('评价对方',`<form id="v7-review-form" class="feedbackform"><input name="id" type="hidden" value="${esc(v)}"><label>评分<select name="rating"><option value="5">5 · 很满意</option><option value="4">4 · 满意</option><option value="3">3 · 一般</option><option value="2">2 · 不满意</option><option value="1">1 · 很不满意</option></select></label><textarea name="text" required placeholder="描述实际合作体验"></textarea><button class="primary">提交评价</button></form>`);if(['accept','confirm','demo-confirm','cancel','approve','reject'].includes(a)){if(!v7SaveAction(v,a))toast('当前身份、任务状态或截止时间不允许该操作')}vRender()});
document.addEventListener('change',e=>{if(vFormId(e.target)==='v7-category'){V7.category=e.target.value;vRender()}});
document.addEventListener('submit',e=>{const id=vFormId(e.target);if(!id.startsWith('v7-'))return;e.preventDefault();const f=Object.fromEntries(new FormData(e.target));if(id==='v7-location-form')V7.location=f.location;if(id==='v7-task-form'){const duration=Number(f.duration),reward=Number(f.reward);if(!f.title?.trim()||!f.place?.trim()||!f.detail?.trim()||!Number.isFinite(duration)||duration<1||duration>1440||!Number.isFinite(reward)||reward<0||reward>100000||!V7TYPES.includes(f.category))return toast('请检查任务内容、时长与奖励');if(f.coordinates&&!vResolve(f.coordinates))return toast('坐标未匹配，请使用深圳范围内的纬度,经度');if(f.deadline&&new Date(f.deadline+':00+08:00')<=businessNow())return toast('截止时间须在未来');V7.location=f.myLocation||V7.location;delete f.myLocation;const rows=v7Rows(),now=businessNow().toISOString();rows.push({...f,id:vId(),source:'private',owner:V7.uid,ownerName:V5.profile.name,duration,reward,created:now,updated:now,status:'审核中',history:[{time:now,status:'审核中',action:'submit'}]});save('sy-v7-tasks',rows);toast('任务已保存，等待维护游客本地审核')}if(id==='v7-complete-form'){if(!v7SaveAction(f.id,'complete',f.note||''))return toast('无法提交，请检查任务状态与完成说明');$('#source-dialog').close()}if(id==='v7-review-form'){if(!v7SaveReview(f.id,Number(f.rating),f.text||''))return toast('仅已完成任务的双方可各评价一次');$('#source-dialog').close()}vRender()});
vRender();

vAbout=function(){return v5Personal()+v6AboutBase()+v5End('关于与设置')};
vRender();
